INSERT INTO public."sys_AIDexterDataDomains" VALUES
	('customs_calculations', 'Customs calculation evidence', 'Recorded duty/VAT estimates and audited overrides. Search must be the exact authorised declaration UUID obtained from customs_declarations. Includes source record IDs, saved workings, rule version and stale state. This reads evidence only: no calculation, override, filing or watch action is provided by this domain.', 'multideck_dexter_domain_customs_calculations', 26, true, '2026-09-14 21:29:57.74132+00', '["Customs.Read"]', '[]', 'company'),
	('leads', 'Leads', 'CRM leads, ownership and next actions with guarded company, contact and email recovery.', 'multideck_dexter_domain_leads', 20, true, '2026-08-03 15:33:05.80462+00', '["CRM.Read"]', '["business_record", "contact_details"]', 'company'),
	('deals', 'Deals', 'CRM opportunities and pipeline evidence with guarded deal-name recovery.', 'multideck_dexter_domain_deals', 30, true, '2026-08-03 15:33:05.80462+00', '["CRM.Read"]', '["business_record", "contact_details"]', 'company'),
	('customers', 'Companies', 'Companies, roles, legal-entity defaults, AR/AP status, controlled payment and tax terms, multi-currency preferences, masked verified bank-account registers, customs profiles, instructions, documents and contact relationships.', 'multideck_dexter_domain_customers', 30, true, '2026-08-29 17:41:17.20766+00', '["Customers.Read"]', '["business_record", "contact_details"]', 'company'),
	('quotes', 'Quotes', 'Customer quotes with branch-relative calculated direction, route, response evidence, delivery evidence, linked booking provenance, outcomes and pricing. Issue readiness checks every structured cargo line and its saved-version consistency; incomplete drafts can still autosave. Discarding working Quote drafts is operator-only; direct the user to Quote actions. Do not claim to discard or recover drafts.', 'multideck_dexter_domain_quotes_intelligence', 40, true, '2026-09-06 08:30:35.28048+00', '["Quotes.Read"]', '["business_record", "commercial_amounts"]', 'company'),
	('contact_cards', 'Contact cards', 'QR contact cards, exchanges, automation health and recent run evidence.', 'multideck_dexter_domain_contact_cards', 35, true, '2026-08-03 21:56:32.435909+00', '[]', '[]', 'company'),
	('marketing_consent', 'Marketing consent', 'Read-only marketing opt-in status and evidence for leads, contacts and customer accounts. Changes require the explicit record toggle.', 'multideck_dexter_domain_marketing_consent', 36, true, '2026-08-03 22:17:50.308511+00', '[]', '[]', 'company'),
	('contacts', 'Contacts', 'Account contacts, role, relationship, communication preference and last-contact evidence. Profile edits remain available in the structured contact form.', 'multideck_dexter_domain_contacts', 31, true, '2026-08-03 22:48:20.19271+00', '[]', '[]', 'company'),
	('customs_assessments', 'Customs assessment comparisons', 'Saved comparisons against the calculation linked at submission. Search requires the exact authorised declaration UUID. Includes evidence/source IDs, adapter version, exact differences and incomplete reasons. A matched estimate is not rule certification. No raw provider envelope or independent AI arithmetic.', 'multideck_dexter_domain_customs_assessments', 27, true, '2026-09-15 00:02:04.452876+00', '["Customs.Read"]', '[]', 'company'),
	('rates', 'Rates and contracts', 'Company-scoped freight contracts and tariffs, including mode, lane, eligibility, validity, commercial totals, current immutable version and source evidence.', 'multideck_dexter_domain_rates', 18, true, '2026-08-10 16:24:31.267438+00', '[]', '[]', 'company'),
	('broadcasts', 'Developer broadcasts', 'Permission-gated broadcast drafts, audience counts and immutable delivery history.', 'multideck_dexter_domain_broadcasts', 85, true, '2026-08-13 11:01:46.620576+00', '[]', '[]', 'company'),
	('drive', 'Drive', 'Files and folders stored in the company Drive, with the folder they sit in, size, type and who added them.', 'multideck_dexter_domain_drive', 38, true, '2026-08-18 10:18:34.713738+00', '["CRM.Drive.Read"]', '[]', 'company'),
	('warehouse', 'Warehouse', 'Warehouse orders, goods-in receipts, goods-out dispatches, warehouse-specific SKU totals and exact inventory balances, movements, pallets and unresolved exceptions. Dexter can use explicit approval-safe actions for connected operational writes.', 'multideck_dexter_domain_warehouse', 10, true, '2026-09-04 12:30:57.72776+00', '["Warehouse.Read"]', '["business_record", "warehouse_details", "commercial_amounts"]', 'company'),
	('todo', 'Tasks', 'Your personal tasks, dates, status and delegated Dexter agent progress.', 'multideck_dexter_domain_todo', 8, true, '2026-08-20 08:26:48.78058+00', '[]', '["personal_productivity", "business_record_references"]', 'owner'),
	('inbox_suggestions', 'Inbox suggested updates', 'Reviewable freight booking and invoice updates with source-backed freight evidence or an exact verified job reference. Unrelated purchases and unconfirmed documents remain in the original Inbox.', 'multideck_dexter_domain_inbox_suggestions', 58, true, '2026-09-02 14:03:10.727273+00', '["Email.Read", "Email.AIRead", "Bookings.Read"]', '["email_metadata", "document_content", "business_record_references"]', 'owner'),
	('usage', 'Usage', 'Current included and extra usage in customer-facing units for AI, OCR, shipment tracking, generated documents and enabled customs services.', 'multideck_dexter_domain_usage', 95, true, '2026-09-02 16:16:27.505091+00', '[]', '[]', 'company'),
	('purchase_orders', 'Expected receipts', 'Customer-provided expected inbound goods, their customer PO reference, supplier, dates, reference totals, matched warehouse items and linked inbound warehouse order.', 'multideck_dexter_domain_purchase_orders', 45, true, '2026-09-09 12:19:49.687976+00', '["Warehouse.Read"]', '["business_record", "warehouse_details", "commercial_amounts"]', 'company'),
	('reference_settings', 'Reference rules', 'Administrator-controlled quote, booking and customer reference formats. Existing records and their canonical links update immediately; previous references remain available as scoped aliases.', 'multideck_dexter_domain_reference_settings', 95, true, '2026-08-20 23:21:40.072893+00', '[]', '[]', 'company'),
	('customs_declarations', 'Customs declarations', 'Authorised company Customs import and export declarations, including responsible user, iCustoms filing evidence, and declaration document availability and receipt time. Document binaries remain available only through the authenticated Customs workspace.', 'multideck_dexter_domain_customs_declarations', 25, true, '2026-08-21 13:17:27.75715+00', '["Customs.Read"]', '["business_record", "customs_details", "commercial_amounts"]', 'company'),
	('phone_calls', 'Phone calls', 'Tenant phone calls with provider evidence, match state, transcript availability, summaries and reviewed follow-up state.', 'multideck_dexter_domain_phone_calls', 22, true, '2026-08-22 14:14:06.870211+00', '["CRM.PhoneCalls.Read"]', '["call_metadata", "contact_data", "transcript", "ai_assistance"]', 'company'),
	('screening', 'Party screening', 'UK Sanctions List freshness and completed screening evidence. Automatic refresh failure or an expired check prevents a reliable no-match result.', 'multideck_dexter_domain_screening', 26, true, '2026-08-20 10:40:25.564715+00', '["Screening.Read"]', '["business_record", "compliance_details"]', 'company'),
	('bookings', 'Freight bookings', 'Canonical freight bookings with branch-relative calculated direction, accepted-quote provenance and the main route and cargo summary. Booking lifecycle: draft means Provisional; open/booked/in_transit/arrived/delivered/ready_for_invoice mean In progress; complete/completed mean Complete. Cancelled and archived remain distinct. Provisional jobs are excluded from job financial summaries. Financial records require progression to In progress. Provisional bookings must have no financial records: invoices, charge lines, job allocations, accruals and WIP require progression first. Accepted-quote charges stay in the source quote until progression. Existing historical finance evidence is retained.', 'multideck_dexter_domain_bookings', 15, true, '2026-09-04 16:00:17.979941+00', '["Bookings.Read"]', '["business_record", "route_details"]', 'company'),
	('lifecycle_notes', 'Operational notes', 'Permission-scoped company, quote, booking and Customs notes. Includes exact note and record IDs, authors, timestamps and evidence. Company notes remain on the company record.', 'multideck_dexter_domain_lifecycle_notes_v2', 46, true, '2026-09-07 09:01:59.375805+00', '[]', '["operational_notes", "workspace_users", "departments"]', 'record'),
	('lifecycle_note_targets', 'Note tag targets', 'Active people and departments in this physical tenant. Use exact returned targetType and recordId values only when adding an operational note; the note write still checks that each recipient can read the selected record.', 'multideck_dexter_domain_lifecycle_note_targets', 47, true, '2026-08-27 09:39:49.101376+00', '[]', '["workspace_users", "departments"]', 'company'),
	('calendar', 'Calendar', 'The signed-in operator''s Multideck meetings with source identifiers, provider state and confirmed times.', 'multideck_dexter_domain_calendar', 9, true, '2026-09-01 20:19:34.325128+00', '["Calendar.Read"]', '["calendar", "crm_activity", "contact_details"]', 'permission'),
	('booking_milestones', 'Booking routing milestones', 'Exact saved milestones with independent planned, estimated and actual times, source and mode evidence. Search by exact Booking reference, Booking/leg/milestone ID. A limited list is not complete history. Customs release excluded.', 'multideck_dexter_domain_booking_milestones', 100, true, '2026-09-07 09:04:46.806838+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('support_tickets', 'Support tickets', 'Minimal public status and reply signals for the signed-in reporter, or all ordinary workspace tickets for a tenant administrator. Ticket bodies and restricted security concerns stay in Multideck Cloud.', 'multideck_dexter_domain_support_tickets', 82, true, '2026-09-02 16:16:32.634366+00', '[]', '["support", "ticket_status", "notifications"]', 'reporter_or_tenant_admin'),
	('booking_links', 'Booking links', 'The signed-in operator''s reusable booking links: kind (one-to-one, round robin or collective), hosts, required public-form questions and publication state.', 'multideck_dexter_domain_booking_links', 10, true, '2026-09-02 16:16:37.227929+00', '["Calendar.BookingLinks.Manage"]', '["calendar", "public_link"]', 'owner'),
	('quote_follow_up_policy', 'Quote follow-up policy', 'Administrator-controlled timing for one automatic reminder on submitted quotes. Customer account preferences and per-customer delays can suppress or override the company default.', 'multideck_dexter_domain_quote_follow_up_policy', 96, true, '2026-09-04 10:53:01.83155+00', '[]', '[]', 'company'),
	('booking_milestone_types', 'Operational milestone choices', 'Current active operational milestone codes and names. Read before proposing a new milestone. Customs release excluded.', 'multideck_dexter_domain_booking_milestone_types', 100, true, '2026-09-07 09:04:46.806838+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('external_events', 'Synced calendar events', 'Upcoming Google and Microsoft calendar events mirrored for the signed-in operator, including whether each event can be edited or answered, the operator''s current response, and a provider-supplied join link when one exists.', 'multideck_dexter_domain_external_events', 11, true, '2026-09-04 11:10:56.308908+00', '["Calendar.Read"]', '["calendar"]', 'owner'),
	('report_sources', 'Report data and fields', 'Read first to discover authorised data sources, field definitions and a complete query example. No arbitrary SQL or joins. Monetary totals require one currency.', 'multideck_dexter_domain_report_sources', 100, true, '2026-09-07 21:50:04.897746+00', '[]', '["operational"]', 'company'),
	('booking_allocations', 'Booking cargo allocation plan', 'Read one complete plan by exact Booking reference or ID. Includes saved cargo/equipment/leg identities and cargo totals. Empty search returns no records. No prices, container totals, VGM or legacy quantity inference.', 'multideck_dexter_domain_booking_allocations', 100, true, '2026-09-06 08:30:43.8844+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('booking_containers', 'Booking equipment', 'Exact active container, ULD, vehicle, trailer and wagon records: kind, number, type, weight and temperature evidence. No costs, margins or raw JSON. Adding/removing equipment and identity corrections currently require Booking Details.', 'multideck_dexter_domain_booking_containers', 100, true, '2026-09-06 08:30:39.856485+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('booking_routes', 'Booking routing legs', 'Exact routing legs, mode-specific references and planned dates. Search by Booking reference or exact route ID. Retained off-mode fields are not current evidence. No financial or raw JSON data. Includes manually recorded cargo, documentation and Sea VGM cut-offs; not actual completion or tracking events.', 'multideck_dexter_domain_booking_routes', 100, true, '2026-09-06 08:30:40.400467+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('booking_dangerous_goods', 'Booking dangerous-goods evidence', 'Supplied per-cargo records, source, unknown flags and retained void history. Exact Booking reference or Booking/cargo/record UUID search. Legacy flags are not proof of confirmation. Limited results are not complete history; no classification or compliance approval.', 'multideck_dexter_domain_booking_dangerous_goods', 100, true, '2026-09-07 11:12:30.236444+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('booking_shipment_value', 'Shipment values', 'Separate shipment goods amount/currency and operator chargeableWeightOverrideKg, as exact text. Null is unknown. Not freight charges, a cargo total/allocation, historical Quote value or AWB weight.', 'multideck_dexter_domain_booking_shipment_value', 100, true, '2026-09-06 08:30:41.501272+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('booking_security_evidence', 'Booking screening evidence', 'Supplied cargo screening status, method, source and retained history. Search exact Booking reference or Booking/cargo/evidence UUID. Unknown stays not recorded; this is not clearance, agent verification or an air waybill. Limited results are not complete history.', 'multideck_dexter_domain_booking_security_evidence', 100, true, '2026-09-07 14:48:27.226466+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('reports', 'Saved reports', 'Read report definitions, ownership, versions and the latest personal run status. Results are not included in this domain; open Reports to preview the actual data. Share definitions only with users who already have the underlying permissions.', 'multideck_dexter_domain_reports', 100, true, '2026-09-07 21:50:04.897746+00', '[]', '["operational"]', 'company'),
	('quote_cargo', 'Quote version cargo', 'Exact current-version cargo lines with draft editability, source identities and exact decimals. No charges, margins or raw snapshots. Per-line handling details and TBC resolution are not supported by this Dexter read adapter; direct the operator to Quote Goods or Booking Cargo. Do not infer readiness from the hazard/temperature flags.', 'multideck_dexter_domain_quote_cargo', 100, true, '2026-09-06 08:30:42.300463+00', '["Quotes.Read"]', '["operational"]', 'company'),
	('booking_cargo', 'Booking cargo lines', 'Individual active cargo lines with exact cargo and booking IDs, quantities, dimensions and safety flags. Decimal measurements are returned as exact text: preserve every digit. Search by booking reference or cargo ID. No selling prices, costs or margins. Editing requires approval; allocation, removal and adding lines must use Booking Details. Includes typed per-line chargeable weight in kilograms; unknown remains null and is not inferred from gross weight or AWB documents. Per-line handling details and TBC resolution are not supported by this Dexter read adapter; direct the operator to Quote Goods or Booking Cargo. Do not infer readiness from the hazard/temperature flags.', 'multideck_dexter_domain_booking_cargo', 100, true, '2026-09-07 13:38:11.212912+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('warehouse_execution', 'Warehouse execution', 'Tenant-safe putaway and pick-task evidence with the typed operational source of the linked warehouse order.', 'multideck_dexter_domain_warehouse_execution', 19, true, '2026-09-09 12:19:49.687976+00', '["Warehouse.Read"]', '["business_record", "warehouse_details"]', 'company'),
	('deal_move_state', 'Deal move review', 'Exact deal ID lookup with saved pipeline, stage, edit version and probability. Query before proposing a pipeline move.', 'multideck_dexter_domain_deal_move_state', 31, true, '2026-09-09 20:47:19.633743+00', '["CRM.Read"]', '["business_record"]', 'canonical'),
	('deal_stage_options', 'Pipeline stages', 'Active stages with pipeline identity, names, probability and review timestamps. Search by pipeline ID/name or stage ID/name. Conversion stages require the deal-won workflow.', 'multideck_dexter_domain_deal_stage_options', 32, true, '2026-09-09 20:47:19.633743+00', '["CRM.Read"]', '["business_record"]', 'canonical'),
	('booking_summary', 'Booking counts', 'Exact total and saved-status counts for all accessible non-deleted bookings. Use an empty search. Explain which status groups you count as active; closed dates are reported separately. Query bookings for individual examples. Count-threshold watching is not supported; existing booking watches track individual status changes. Booking lifecycle: draft means Provisional; open/booked/in_transit/arrived/delivered/ready_for_invoice mean In progress; complete/completed mean Complete. Cancelled and archived remain distinct. Provisional jobs are excluded from job financial summaries. Financial records require progression to In progress.', 'multideck_dexter_domain_booking_summary', 100, true, '2026-09-09 22:40:07.308317+00', '["Bookings.Read"]', '["operational"]', 'company'),
	('finance', 'Finance', 'Tenant-safe native financial summaries, trial-balance evidence, AR/AP, cash, freight charge profitability, external mirror state and jurisdiction compliance obligations. Payroll is excluded. Provisional bookings must have no financial records: invoices, charge lines, job allocations, accruals and WIP require progression first. Accepted-quote charges stay in the source quote until progression. Existing historical finance evidence is retained.', 'multideck_dexter_domain_finance', 26, true, '2026-09-01 19:04:36.60945+00', '["Finance.Receivables.View", "Finance.Payables.View"]', '["financial", "customer", "supplier", "configuration"]', 'company'),
	('email_signatures', 'Email signatures', 'Available Multideck signature names, published versions and authorised assignment evidence. Visual editing, publishing and policy changes require the signature builder; chat cannot perform those writes.', 'multideck_dexter_domain_email_signatures', 62, true, '2026-09-11 14:52:27.40859+00', '[]', '[]', 'company');
INSERT INTO public."sys_AIDexterActions" VALUES
	('calculate_customs_duties', 'customs_calculations', 'Calculate Customs duty and VAT estimates', 'After approval, calculate the saved import declaration using the same authorised calculation service as the UI. Save an immutable audit snapshot. Never submit or change declared tax fields.', 'multideck_dexter_action_icustoms_edge_only', '{"type": "object", "required": ["target_id", "reason"], "properties": {"reason": {"type": "string", "maxLength": 2000, "minLength": 10}, "target_id": {"type": "string"}}, "additionalProperties": false}', 134, true, '2026-09-14 21:29:58.811783+00', '["Customs.Write"]', 'calculate_customs_duties', 'canonical', true, true),
	('override_customs_calculation', 'customs_calculations', 'Record an audited estimate override', 'After approval, record exact replacement duty/VAT amounts and a mandatory reason against an existing current calculation and item. Original figures remain immutable. This is estimate-only, not a manual CDS tax override.', 'multideck_dexter_action_icustoms_edge_only', '{"type": "object", "required": ["target_id", "calculation_id", "item_id", "duty", "vat", "reason"], "properties": {"vat": {"type": "string", "pattern": "^[0-9]{1,16}\\.[0-9]{2}$"}, "duty": {"type": "string", "pattern": "^[0-9]{1,16}\\.[0-9]{2}$"}, "reason": {"type": "string", "maxLength": 2000, "minLength": 10}, "item_id": {"type": "string"}, "target_id": {"type": "string"}, "calculation_id": {"type": "string"}}, "additionalProperties": false}', 135, true, '2026-09-14 21:29:58.811783+00', '["Customs.Write"]', 'override_customs_calculation', 'canonical', true, true),
