	('create_support_ticket', 'support_tickets', 'Create support ticket', 'Create one ordinary Multideck support ticket for the signed-in operator through Cloud intake. Always requires explicit approval. Screenshots and restricted security concerns must use Submit a ticket.', 'multideck_dexter_action_create_support_ticket', '{"type": "object", "required": ["ticket_type", "impact", "title", "description", "expected_behaviour", "actual_behaviour", "desired_outcome"], "properties": {"title": {"type": "string", "maxLength": 180, "minLength": 4}, "impact": {"enum": ["blocked", "slowed_down", "no_immediate_blocker"], "type": "string"}, "description": {"type": "string", "maxLength": 12000, "minLength": 10}, "ticket_type": {"enum": ["bug", "feature_request", "question", "account_billing"], "type": "string"}, "desired_outcome": {"type": ["string", "null"], "maxLength": 6000}, "actual_behaviour": {"type": ["string", "null"], "maxLength": 6000}, "expected_behaviour": {"type": ["string", "null"], "maxLength": 6000}}, "additionalProperties": false}', 825, true, '2026-09-02 16:16:32.634366+00', '[]', 'support_ticket_creation', 'signed_in_reporter', true, false),
